INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES
(235,0,0,'Thank you, $n. Your kindness will not be forgotten.',12,7,100,2,0,0,42468,0,'Salma Saldean to Player'),
(235,1,0,'Dinner\'s ready! Come and get it!',14,7,100,22,0,0,42469,0,'Salma Saldean to Player'),
(42308,0,0,'No kidding, rookie...',12,7,100,273,0,0,42227,0,'Lieutenant Horatio Laine to Player'),
(42308,1,0,'Looks like they really put the cart...',12,7,100,0,0,0,42228,0,'Lieutenant Horatio Laine to Player'),
(42308,2,0,'...before the horse.',12,7,100,0,0,0,42229,0,'Lieutenant Horatio Laine to Player'),
(42308,3,0,'That\'s good to hear, marshal. While $n has brought the perpetrators to justice, their ringleader is still on the loose. Perhaps with the aid of the Westfall Brigade we will finally be able to solve this case.',12,0,100,1,0,0,42506,0,'Lieutenant Horatio Laine to Player'),
(42308,4,0,'Might I ask, what\'s with the worgen in the stocks?',12,0,100,6,0,0,42507,0,'Lieutenant Horatio Laine to Player'),
(42308,5,0,'Wow, the marshal wasn\'t kidding.',12,0,100,0,0,0,42510,0,'Lieutenant Horatio Laine to Player'),
(42308,6,0,'But is your bark...',12,0,100,0,0,0,42511,0,'Lieutenant Horatio Laine to Player'),
(42308,7,0,'Worse than your bite?',12,0,100,0,0,0,42512,0,'Lieutenant Horatio Laine to Player'),
(42558,0,0,'Doesn\'t look good, rookie.',12,7,100,1,0,0,42447,0,'Lieutenant Horatio Laine to Player'),
(42558,1,0,'This was an execution. Whoever did this was sending a message...',12,7,100,0,0,0,42449,0,'Lieutenant Horatio Laine to Player'),
(42558,2,0,'A message for anyone that would dare snitch on these criminals.',12,7,100,0,0,0,42450,0,'Lieutenant Horatio Laine to Player'),
(42558,3,0,'It would appear that poor Lou really put his foot...',12,7,100,0,0,0,42451,0,'Lieutenant Horatio Laine to Player'),
(42558,4,0,'In his mouth.',12,7,100,0,0,0,42452,0,'Lieutenant Horatio Laine to Player'),
(54371,0,0,'More bones to gnaw on...',12,0,50,0,0,0,46596,0,'on Aggro Text'),
(54371,0,1,'Grrrr... fresh meat!',12,0,50,0,0,0,1870,0,'on Aggro Text'),
(54372,0,0,'More bones to gnaw on...',12,0,50,0,0,0,46596,0,'on Aggro Text'),
(54372,0,1,'Grrrr... fresh meat!',12,0,50,0,0,0,1870,0,'on Aggro Text'),
(54373,0,0,'More bones to gnaw on...',12,0,50,0,0,0,46596,0,'on Aggro Text'),
(54373,0,1,'Grrrr... fresh meat!',12,0,50,0,0,0,1870,0,'on Aggro Text');
